import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const d=JSON.parse('{"title":"Technical Support – My Ticket","description":"","frontmatter":{"title":"Technical Support – My Ticket"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/technical-support-my-ticket.md","filePath":"operations-knowledge-base/presales-support/technical-support-my-ticket.md","lastUpdated":1794292919000}'),r={name:"operations-knowledge-base/presales-support/technical-support-my-ticket.md"};function o(l,e,n,c,p,u){return i(),s("div",null,[...e[0]||(e[0]=[a('<h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>The ticket system is a communication tool provided by the platform that allows users to contact and work with the support team.</p><p>Users can submit tickets to report issues or request assistance, and view all ticket statuses and history in the “My Tickets” section. This helps users track the progress of their requests and ensures that issues are handled in a timely manner.</p><h2 id="_2-my-tickets" tabindex="-1">2. My Tickets <a class="header-anchor" href="#_2-my-tickets" aria-label="Permalink to &quot;2. My Tickets&quot;">​</a></h2><h3 id="_1-access-path" tabindex="-1">(1) Access Path <a class="header-anchor" href="#_1-access-path" aria-label="Permalink to &quot;(1) Access Path&quot;">​</a></h3><p>Navigate through the platform menu:</p><p>Customer Center → Support → My Tickets</p><h3 id="_2-feature-description" tabindex="-1">(2) Feature Description <a class="header-anchor" href="#_2-feature-description" aria-label="Permalink to &quot;(2) Feature Description&quot;">​</a></h3><p>The page displays a list of ticket records. Users can filter tickets by status using the following tabs:</p><ul><li>Pending</li><li>Answered</li><li>Customer Reply</li><li>Open</li><li>Closed</li><li>Responses</li></ul><p>The ticket list includes the following information:</p><ul><li>Issue type</li><li>Subject</li><li>Status</li><li>Last Updated</li></ul><p>This allows users to quickly understand the current status of their tickets.</p><p>A search box in the upper-right corner also allows users to enter keywords to quickly locate specific tickets.</p><h2 id="_3-submit-a-new-ticket" tabindex="-1">3. Submit a New Ticket <a class="header-anchor" href="#_3-submit-a-new-ticket" aria-label="Permalink to &quot;3. Submit a New Ticket&quot;">​</a></h2><h3 id="_1-access-path-1" tabindex="-1">(1) Access Path <a class="header-anchor" href="#_1-access-path-1" aria-label="Permalink to &quot;(1) Access Path&quot;">​</a></h3><p>On the “My Tickets” page, click the “Open New Ticket” button to enter the “Open Ticket” page.</p><h3 id="_2-feature-description-1" tabindex="-1">(2) Feature Description <a class="header-anchor" href="#_2-feature-description-1" aria-label="Permalink to &quot;(2) Feature Description&quot;">​</a></h3><h4 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to &quot;Basic Information&quot;">​</a></h4><p><strong>Name</strong> The system automatically fills in the user’s name (e.g., “Rak Internal Test”), so manual entry is not required.</p><p><strong>Email Address</strong> The system automatically fills in the user’s email address to ensure ticket notifications are delivered correctly.</p><p><strong>Subject</strong> Enter a clear and concise subject that summarizes the issue or request, so the support team can quickly identify the main problem.</p><p><strong>Issue type</strong> Please select the most appropriate category based on the issue you are experiencing. Choosing the correct category helps route your ticket to the appropriate team more quickly and reduce response time.</p><ul><li><p><strong>Performance Issue (Technical Support)</strong> Used for technical issues related to platform products or services, such as:</p><ul><li>System errors</li><li>Feature malfunctions</li><li>Network connectivity issues</li><li>Product configuration questions</li></ul><p>The technical support team can diagnose, troubleshoot, and resolve technical issues related to platform products such as servers, cloud services, and applications. They can also provide usage guidance and technical optimization recommendations.</p></li><li><p><strong>Product issue</strong> Choose this department for product or service purchase inquiries, including:</p><ul><li>Pricing questions</li><li>Package or plan selection</li><li>Promotion details</li><li>Partnership discussions</li></ul><p>The sales team helps users select suitable products and explains available packages, promotions, and cooperation options.</p></li><li><p><strong>Pricing and Billing issue</strong> Used for financial or billing-related issues, such as:</p><ul><li>Questions about invoice amounts</li><li>Payment method inquiries</li><li>Billing anomalies (e.g., duplicate charges or missing invoices)</li></ul><p>The billing team helps review billing details, assist with payments, and handle invoice-related requests.</p></li></ul><p><strong>Related Service</strong> Select the service associated with the ticket from the dropdown list.</p><p>If needed, you can enable the “Hide Inactive Products” checkbox to hide inactive services.</p><p><strong>Message Description</strong> In the “Message” editor, provide a detailed description of the issue or request.</p><p>You may use formatting tools (such as bold, italic, or links) to improve clarity and help the support team better understand the problem.</p><p><strong>Attachments Upload</strong> If supporting files are needed (such as screenshots or logs), click “Choose File” to upload attachments.</p><p>Supported file types:</p><ul><li>.jpg</li><li>.gif</li><li>.jpeg</li><li>.png</li><li>.txt</li><li>.pdf</li></ul><p>Requirements:</p><ul><li>Maximum size per <a href="https://raksmart.atlassian.net/wiki/spaces/~71202041a52665b12646ffad1499b55d7f254c/pages/8671363108/Technical+Support+My+Ticket#" title="#" target="_blank" rel="noreferrer">file:</a> 1 MB</li><li>Chinese characters in file names are not supported</li></ul><p>To upload multiple files, click “+ Add More”.</p><p><strong>Submit or Cancel</strong></p><ul><li>Click “Submit” to send the ticket to the selected department’s support team.</li><li>Click “Cancel” if you decide not to submit the ticket.</li></ul><p>Through the ticket system, users can communicate efficiently with the platform’s support team, resolve issues encountered during service use, and improve the overall support experience.</p>',37)])])}const m=t(r,[["render",o]]);export{d as __pageData,m as default};
